import{_ as a,C as s,o as d,c as i,a2 as e,E as o}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Product Approval","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-approval.md","filePath":"catalog/product-approval.md","lastUpdated":1789411447000}'),n={name:"catalog/product-approval.md"};function l(p,t,c,g,u,h){const r=s("ImagePopup");return d(),i("div",null,[t[0]||(t[0]=e('<h1 id="product-approval" tabindex="-1">Product Approval <a class="header-anchor" href="#product-approval" aria-label="Permalink to &quot;Product Approval&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>A seller&#39;s product starts as a draft, is submitted when it is ready and, if the store requires it, is approved by the admin before customers can buy it. This page follows a product through each step, from both sides.</p><h2 id="product-statuses" tabindex="-1">Product statuses <a class="header-anchor" href="#product-statuses" aria-label="Permalink to &quot;Product statuses&quot;">​</a></h2><p>Sellers see the status as a badge on each product in <strong>Catalog &gt;&gt; Products</strong>.</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>The seller is still working on the product. Only the seller can see it.</td></tr><tr><td><strong>Waiting For Approval</strong></td><td>The seller submitted the product and the admin hasn&#39;t decided yet.</td></tr><tr><td><strong>Approved</strong></td><td>The product can be sold.</td></tr><tr><td><strong>Rejected</strong></td><td>The admin rejected the product. The reason is shown under the badge.</td></tr></tbody></table>',6)),o(r,{src:"/images/product-approval/seller-products-statuses.png",alt:"Seller products with Draft, Waiting For Approval, Approved and Rejected badges"}),t[1]||(t[1]=e('<p>To find products by status, click <strong>Filter</strong> and use <strong>Is Approved</strong> (<strong>Approved</strong>, <strong>Waiting For Approval</strong> or <strong>Rejected</strong>) or <strong>Draft Status</strong> (<strong>Draft</strong> or <strong>Submitted</strong>).</p><h2 id="save-a-draft" tabindex="-1">Save a draft <a class="header-anchor" href="#save-a-draft" aria-label="Permalink to &quot;Save a draft&quot;">​</a></h2><p>While a product is a draft, its edit page shows <strong>Save as Draft</strong> and <strong>Submit</strong>. Click <strong>Save as Draft</strong> to keep your work and come back to it later.</p><p>A draft is still checked when you save it, so fill in the fields marked as required, such as the name, price, weight, short description and description, before you click <strong>Save as Draft</strong>.</p><p>Drafts aren&#39;t shown to the admin, and they can&#39;t be sold.</p><h2 id="submit-a-product" tabindex="-1">Submit a product <a class="header-anchor" href="#submit-a-product" aria-label="Permalink to &quot;Submit a product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Click the edit arrow on the draft.</li><li>Check that the details are complete.</li><li>Click <strong>Submit</strong>.</li></ol><p>If the store approves products, the product now shows <strong>Waiting For Approval</strong>. If it doesn&#39;t, the product is approved straight away.</p><p>Once submitted, the edit page shows <strong>Save Product</strong> instead, and the product can&#39;t go back to being a draft.</p><h2 id="approve-products" tabindex="-1">Approve products <a class="header-anchor" href="#approve-products" aria-label="Permalink to &quot;Approve products&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Products</strong>.</li><li>Tick the products you want to approve.</li><li>Click <strong>Select Action</strong>, point to <strong>Update Status</strong> and click <strong>Approved</strong>.</li><li>Click <strong>Agree</strong> to confirm.</li></ol>',11)),o(r,{src:"/images/product-approval/admin-products.png",alt:"Seller products waiting for approval in the admin panel"}),t[2]||(t[2]=e('<p>Each seller receives an email saying their product has been approved.</p><p>The list shows submitted products from every seller, including products they sell from your catalog. Each row shows the product, its price and stock, the seller, whether the seller owns the product (<strong>Is Owner</strong>), its status and how many times customers have reported it.</p><p>A product is skipped if its seller isn&#39;t approved. When the store uses subscription plans, it is also skipped if the seller has no plan, or if approving it would take the seller past their plan&#39;s product limit.</p><h2 id="reject-a-product" tabindex="-1">Reject a product <a class="header-anchor" href="#reject-a-product" aria-label="Permalink to &quot;Reject a product&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Products</strong>.</li><li>Click the reject icon on the product&#39;s row.</li><li>In <strong>Rejection Reason</strong>, explain what the seller needs to fix.</li><li>Click <strong>Reject Product</strong>.</li></ol>',5)),o(r,{src:"/images/product-approval/reject-product.png",alt:"The Reject Product dialog"}),t[3]||(t[3]=e('<p>The seller receives an email with your reason, and the reason appears under the product&#39;s <strong>Rejected</strong> badge.</p><h2 id="fix-a-rejected-product" tabindex="-1">Fix a rejected product <a class="header-anchor" href="#fix-a-rejected-product" aria-label="Permalink to &quot;Fix a rejected product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Read the reason under the <strong>Rejected</strong> badge. If it is long, click <strong>Read more</strong> to see all of it.</li><li>Click the edit arrow and make the changes.</li><li>Click <strong>Save Product</strong>.</li></ol><p>Saving sends the product back for approval. Its status changes to <strong>Waiting For Approval</strong>.</p><h2 id="editing-an-approved-product" tabindex="-1">Editing an approved product <a class="header-anchor" href="#editing-an-approved-product" aria-label="Permalink to &quot;Editing an approved product&quot;">​</a></h2><p>An approved product stays approved when the seller edits and saves it in the product form. It doesn&#39;t go back to the admin for approval.</p><h2 id="delete-a-product" tabindex="-1">Delete a product <a class="header-anchor" href="#delete-a-product" aria-label="Permalink to &quot;Delete a product&quot;">​</a></h2><ul><li>A seller deletes a product from its row in <strong>Catalog &gt;&gt; Products</strong>.</li><li>The admin deletes it from its row in <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Products</strong>.</li></ul><p>Deleting a product the seller owns removes the product itself. Deleting a product the seller sells from your catalog removes only the seller&#39;s offer.</p><h2 id="settings-and-permissions" tabindex="-1">Settings and permissions <a class="header-anchor" href="#settings-and-permissions" aria-label="Permalink to &quot;Settings and permissions&quot;">​</a></h2><ul><li><strong>Approval Required</strong> in <a href="./../configuration/products">Products settings</a> decides whether products need approval.</li><li>Admins need <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Products &gt;&gt; Edit</strong> to approve and reject, and <strong>Delete</strong> to delete.</li><li>The admin edits a seller&#39;s product details in <strong>Catalog &gt;&gt; Products</strong>, the store&#39;s main product list. The marketplace list has no edit action.</li></ul>',11))])}const v=a(n,[["render",l]]);export{f as __pageData,v as default};
